B = "http://154.57.164.66:41126"

def begin():
    r = requests.post(B+"/begin_session", json={}, timeout=10)
    return r.json()["session_id"]

def measure(s, state, rnd, basis, shots=5):
    r = requests.post(B+"/measure", json={"session_id":s,"state":state,"round":rnd,"basis":basis,"shots":shots}, timeout=15)
    return r.status_code, r.json()

if __name__ == "__main__":
    s = begin()
    print("session", s)
    bases = ["ZZZZZ","XXXXX","YYYYY","ZZZZX","ZXZXY"]
    for state in range(1,9):
        for i,b in enumerate(bases):
            code, j = measure(s, state, i+1, b)
            print(state, b, code, json.dumps(j)[:500])

